mapper.select:
select lines1.CUSTOMER_ID, MST_CUSTOMER_INFO.CUSTOMER_NAME, CREDIT_TAG_INFO.CREDIT_TYPE, CREDIT_CONF_INFO.TERM, CREDIT_CONF_INFO.TERM_UNIT, TEMP1.TOTLEAMOUNT, lines1.CREDIT_MST_ID, rownum xuhao from ( select CREDIT_MST_ID, CUSTOMER_ID from CREDIT_USING_CUSTOMER_AJUST group by CREDIT_MST_ID, CUSTOMER_ID ) lines1 left join ( select TEMP.CUSTOMER_ID, TEMP.CREDIT_MST_ID, SUM(TZAMOUNT)as TOTLEAMOUNT from ( select CUSTOMER_ID, CREDIT_MST_ID, decode(AJUST_TYPE, '01', -1*AMOUNT, AMOUNT) TZAMOUNT from CREDIT_USING_CUSTOMER_AJUST where CDATE <= to_date(#{ptDate}, 'yyyy-MM-dd') UNION select CUSTOMER_ID, CREDIT_MST_ID, decode(AJUST_TYPE, '02', -1*AMOUNT, AMOUNT) TZAMOUNT from CREDIT_USING_CUSTOMER_AJUST where RDATE <= to_date(#{ptDate}, 'yyyy-MM-dd') )TEMP GROUP BY TEMP.CUSTOMER_ID, TEMP.CREDIT_MST_ID )TEMP1 on TEMP1.CUSTOMER_ID = lines1.CUSTOMER_ID and TEMP1.CREDIT_MST_ID = lines1.CREDIT_MST_ID inner JOIN CREDIT_CONF_INFO ON lines1.CREDIT_MST_ID = CREDIT_CONF_INFO.CREDIT_MST_ID LEFT JOIN CREDIT_TAG_INFO on CREDIT_CONF_INFO.CREDIT_TAG_ID = CREDIT_TAG_INFO.CREDIT_TAG_ID LEFT JOIN MST_CUSTOMER_INFO ON lines1.CUSTOMER_ID =MST_CUSTOMER_INFO.CUSTOMER_ID where 1 = 1
and lines1.CUSTOMER_ID = #{object}
and CREDIT_TAG_INFO.CREDIT_TYPE = #{creditName}
and CREDIT_CONF_INFO.TERM = #{term}
and CREDIT_CONF_INFO.TERM_UNIT = #{termUnit}

SELECT distinct SYS_USER.USER_NAME as id, SYS_USER.REAL_NAME as text FROM SYS_USER where 1=1
AND (SYS_USER.USER_NAME like concat(concat('%',#{search}),'%') or SYS_USER.REAL_NAME like concat(concat('%',#{search}),'%') )
and SYS_USER.USER_NAME = #{initValue}

select rownum xuhao, a.SEQNO, a.CUSTOMER_ID, MST_CUSTOMER_INFO.CUSTOMER_NAME, a.CREDIT_MST_ID, CREDIT_TAG_INFO.CREDIT_TYPE, CREDIT_CONF_INFO.TERM, CREDIT_CONF_INFO.TERM_UNIT, a.AJUST_TYPE, a.AMOUNT, a.CDATE, a.RDATE, a.CREATE_USER, SYS_USER.REAL_NAME, a.REMARK from CREDIT_USING_CUSTOMER_AJUST a LEFT JOIN MST_CUSTOMER_INFO ON a.CUSTOMER_ID =MST_CUSTOMER_INFO.CUSTOMER_ID inner JOIN CREDIT_CONF_INFO ON a.CREDIT_MST_ID = CREDIT_CONF_INFO.CREDIT_MST_ID LEFT JOIN CREDIT_TAG_INFO on CREDIT_CONF_INFO.CREDIT_TAG_ID = CREDIT_TAG_INFO.CREDIT_TAG_ID LEFT JOIN SYS_USER on SYS_USER.USER_NAME = a.CREATE_USER where 1 = 1
and a.SEQNO = #{seqno}
and a.CUSTOMER_ID = #{customerId}
and a.CREDIT_MST_ID = #{creditMstId}

select a.* from CREDIT_LINES a inner join CREDIT_CONF_INFO b on a.CREDIT_MST_ID = b.CREDIT_MST_ID inner join CREDIT_TAG_INFO c on c.CREDIT_TAG_ID = b.CREDIT_TAG_ID where c.CREDIT_TAG_NAME is null
and a.CUSTOMER_ID = #{customerId}
and c.CREDIT_TYPE = #{creditType}
and b.TERM = #{term}
and b.TERM_UNIT = #{termUnit}
order by a.PFLSH desc
